import { useCallback, useMemo, useState } from 'react';
import { Button, Card, Stack, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date;
  onChange: (date: Date) => void;
};

const WEEKDAYS = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
const MONTHS = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

const addDays = (d: Date, amount: number) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate() + amount);

const isSameDay = (a: Date, b: Date) =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [internalValue, setInternalValue] = useState<Date>(value ?? today);
  const selected = value ?? internalValue;

  const [viewMonth, setViewMonth] = useState<Date>(
    () => new Date(selected.getFullYear(), selected.getMonth(), 1),
  );

  const select = useCallback(
    (date: Date) => {
      const day = startOfDay(date);
      setInternalValue(day);
      setViewMonth(new Date(day.getFullYear(), day.getMonth(), 1));
      onChange(day);
    },
    [onChange],
  );

  const days = useMemo(() => {
    const firstDay = new Date(viewMonth.getFullYear(), viewMonth.getMonth(), 1);
    // неделя начинается с понедельника, а getDay() возвращает 0 для воскресенья
    const leading = (firstDay.getDay() + 6) % 7;
    const daysInMonth = new Date(viewMonth.getFullYear(), viewMonth.getMonth() + 1, 0).getDate();
    const cells = Math.ceil((leading + daysInMonth) / 7) * 7;

    return Array.from({ length: cells }, (_, i) => addDays(firstDay, i - leading));
  }, [viewMonth]);

  const presets = useMemo(
    () => [
      { label: 'Сегодня', date: today },
      { label: 'Вчера', date: addDays(today, -1) },
      { label: 'Неделя назад', date: addDays(today, -7) },
    ],
    [today],
  );

  const shiftMonth = (amount: number) =>
    setViewMonth((m) => new Date(m.getFullYear(), m.getMonth() + amount, 1));

  return (
    <Card>
      <Stack direction="vertical" gap="md">
        <Stack direction="horizontal" gap="sm">
          {presets.map((preset) => (
            <Button
              key={preset.label}
              variant={isSameDay(selected, preset.date) ? 'primary' : 'secondary'}
              size="sm"
              onClick={() => select(preset.date)}
            >
              {preset.label}
            </Button>
          ))}
        </Stack>

        <Stack direction="horizontal" gap="sm" align="center" justify="space-between">
          <Button variant="ghost" size="sm" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
            ‹
          </Button>
          <Text weight="medium">
            {MONTHS[viewMonth.getMonth()]} {viewMonth.getFullYear()}
          </Text>
          <Button variant="ghost" size="sm" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
            ›
          </Button>
        </Stack>

        <div
          role="grid"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-1)',
          }}
        >
          {WEEKDAYS.map((weekday) => (
            <Text key={weekday} size="sm" tone="muted" align="center">
              {weekday}
            </Text>
          ))}

          {days.map((day) => {
            const outside = day.getMonth() !== viewMonth.getMonth();
            const isSelected = isSameDay(day, selected);

            return (
              <Button
                key={day.toISOString()}
                variant={isSelected ? 'primary' : 'ghost'}
                size="sm"
                aria-pressed={isSelected}
                onClick={() => select(day)}
                style={{ opacity: outside ? 'var(--jx-opacity-muted)' : undefined }}
              >
                {day.getDate()}
              </Button>
            );
          })}
        </div>
      </Stack>
    </Card>
  );
}

